#include <bits/stdc++.h>
using namespace std;

struct P {
    long long x, y;
    P operator+(const P &o) const { return {x + o.x, y + o.y}; }
    P operator-(const P &o) const { return {x - o.x, y - o.y}; }
    bool operator==(const P &o) const { return x == o.x && y == o.y; }
    bool operator<(const P &o) const { return x != o.x ? x < o.x : y < o.y; }
    long long cross(const P &o) const { return x * o.y - y * o.x; }
    long long dot(const P &o) const { return x * o.x + y * o.y; }
    long long norm2() const { return x * x + y * y; }
};

// Podwojone pole ze znakiem (wzór shoelace / Gaussa). > 0: wierzchołki CCW, < 0: CW.
long long twiceSignedArea(const vector<P> &p) {
    __int128 s = 0;                              // sumy częściowe mogą wyjść poza long long
    int n = p.size();
    for (int i = 0; i < n; i++) s += p[i].cross(p[(i + 1) % n]);
    return (long long)s;                         // |2·pole| <= 8·10^18 dla |x|, |y| <= 10^9
}

int main() {
    int n;
    cin >> n;
    vector<P> p(n);
    for (auto &q : p) cin >> q.x >> q.y;
    long long s = twiceSignedArea(p);
    long long a2 = llabs(s);                                  // podwojone pole
    cout << a2 / 2 << (a2 % 2 ? ".5" : "") << "\n";           // pole dokładnie
    cout << (s > 0 ? "CCW" : s < 0 ? "CW" : "ZDEGENEROWANY") << "\n";
}

