#include <bits/stdc++.h>
using namespace std;

struct P {
    long long x, y;
    P operator+(const P &o) const { return {x + o.x, y + o.y}; }
    P operator-(const P &o) const { return {x - o.x, y - o.y}; }
    bool operator==(const P &o) const { return x == o.x && y == o.y; }
    bool operator<(const P &o) const { return x != o.x ? x < o.x : y < o.y; }
    long long cross(const P &o) const { return x * o.y - y * o.x; }
    long long dot(const P &o) const { return x * o.x + y * o.y; }
    long long norm2() const { return x * x + y * y; }
};

// Otoczka wypukła — algorytm Andrew (monotone chain), O(n log n).
// Zwraca wierzchołki CCW, bez duplikatów i bez punktów współliniowych na bokach.
vector<P> convexHull(vector<P> pts) {
    sort(pts.begin(), pts.end());
    pts.erase(unique(pts.begin(), pts.end()), pts.end());
    int n = pts.size();
    if (n <= 2) return pts;
    vector<P> h(2 * n);
    int k = 0;
    for (int i = 0; i < n; i++) {                               // dolna część (od lewej do prawej)
        while (k >= 2 && (h[k - 1] - h[k - 2]).cross(pts[i] - h[k - 2]) <= 0) k--;
        h[k++] = pts[i];
    }
    for (int i = n - 2, lo = k + 1; i >= 0; i--) {              // górna część (od prawej do lewej)
        while (k >= lo && (h[k - 1] - h[k - 2]).cross(pts[i] - h[k - 2]) <= 0) k--;
        h[k++] = pts[i];
    }
    h.resize(k - 1);                                            // ostatni punkt = pierwszy
    return h;
}

int main() {
    int n;
    cin >> n;
    vector<P> pts(n);
    for (auto &p : pts) cin >> p.x >> p.y;
    vector<P> h = convexHull(pts);
    int k = h.size();
    cout << k << "\n";
    for (auto &p : h) cout << p.x << " " << p.y << "\n";
    double per = 0;                                    // obwód (dla 2 punktów: odcinek tam i z powrotem)
    __int128 s = 0;                                    // podwojone pole
    for (int i = 0; i < k; i++) {
        P a = h[i], b = h[(i + 1) % k];
        per += sqrt((double)(b - a).norm2());
        s += a.cross(b);
    }
    long long a2 = (long long)s;                       // >= 0, bo otoczka jest CCW
    cout << fixed << setprecision(6) << per << "\n";
    cout << a2 / 2 << (a2 % 2 ? ".5" : "") << "\n";
}

