    long long dot(const P &o) const { return x * o.x + y * o.y; }
    long long norm2() const { return x * x + y * y; }
};

// Otoczka z zachowaniem punktów współliniowych leżących na bokach (CCW).
vector<P> convexHullAll(vector<P> pts) {
    sort(pts.begin(), pts.end());
    pts.erase(unique(pts.begin(), pts.end()), pts.end());
    int n = pts.size();
    if (n <= 2) return pts;
    bool collinear = true;
    for (int i = 2; i < n; i++)
        if ((pts[1] - pts[0]).cross(pts[i] - pts[0]) != 0) collinear = false;
    if (collinear) return pts;                                  // wszystkie na jednej prostej
    vector<P> h(2 * n);
    int k = 0;
    for (int i = 0; i < n; i++) {
        while (k >= 2 && (h[k - 1] - h[k - 2]).cross(pts[i] - h[k - 2]) < 0) k--;   // < 0 zamiast <= 0
        h[k++] = pts[i];
    }
    for (int i = n - 2, lo = k + 1; i >= 0; i--) {
        while (k >= lo && (h[k - 1] - h[k - 2]).cross(pts[i] - h[k - 2]) < 0) k--;
        h[k++] = pts[i];
    }
    h.resize(k - 1);
    return h;
}

