    long long x, y;
    P operator+(const P &o) const { return {x + o.x, y + o.y}; }
    P operator-(const P &o) const { return {x - o.x, y - o.y}; }
    bool operator==(const P &o) const { return x == o.x && y == o.y; }
    bool operator<(const P &o) const { return x != o.x ? x < o.x : y < o.y; }
    long long cross(const P &o) const { return x * o.y - y * o.x; }
    long long dot(const P &o) const { return x * o.x + y * o.y; }
    long long norm2() const { return x * x + y * y; }
};

// Kwadrat średnicy (największej odległości) — obracające się suwmiarki na otoczce CCW bez współliniowych.
long long diameter2(const vector<P> &h) {
    int n = h.size();
    if (n == 1) return 0;
    if (n == 2) return (h[0] - h[1]).norm2();
    long long best = 0;
    for (int i = 0, j = 1; i < n; i++) {
        int ni = (i + 1) % n;
        // przesuwaj j, dopóki wierzchołek j+1 jest dalej od prostej (h[i], h[ni]) niż j
        while ((h[ni] - h[i]).cross(h[(j + 1) % n] - h[j]) > 0) j = (j + 1) % n;
        best = max({best, (h[i] - h[j]).norm2(), (h[ni] - h[j]).norm2()});
    }
    return best;
}

