    bool operator<(const P &o) const { return x != o.x ? x < o.x : y < o.y; }
    long long cross(const P &o) const { return x * o.y - y * o.x; }
    long long dot(const P &o) const { return x * o.x + y * o.y; }
    long long norm2() const { return x * x + y * y; }
};

// Punkt w wielokącie prostym (dowolna orientacja): 0 — na zewnątrz, 1 — na brzegu, 2 — wewnątrz.
int pointInPolygon(const vector<P> &poly, P p) {
    int n = poly.size();
    bool inside = false;
    for (int i = 0; i < n; i++) {
        P a = poly[i], b = poly[(i + 1) % n];
        if ((b - a).cross(p - a) == 0 && (a - p).dot(b - p) <= 0) return 1;   // p na boku [a, b]
        if ((a.y > p.y) != (b.y > p.y)) {                 // bok przecina poziomą prostą y = p.y
            long long c = (b - a).cross(p - a);           // (reguła półotwarta: wierzchołek liczony raz)
            if ((c > 0) == (b.y > a.y)) inside = !inside; // przecięcie leży na prawo od p
        }
    }
    return inside ? 2 : 0;
}

int main() {
    int n, q;
    cin >> n >> q;
    vector<P> poly(n);
    for (auto &p : poly) cin >> p.x >> p.y;
    const char *name[] = {"OUTSIDE", "BOUNDARY", "INSIDE"};
    while (q--) {
        P p;
        cin >> p.x >> p.y;
        cout << name[pointInPolygon(poly, p)] << "\n";
    }
}

