// 0 — na zewnątrz, 1 — na brzegu, 2 — wewnątrz.
int pointInConvex(const vector<P> &poly, P p) {
    int n = poly.size();
    P o = poly[0];
    if ((poly[1] - o).cross(p - o) < 0 || (poly[n - 1] - o).cross(p - o) > 0) return 0;
    int lo = 1, hi = n - 1;                        // szukamy klina o, poly[lo], poly[lo+1] zawierającego p
    while (hi - lo > 1) {
        int mid = (lo + hi) / 2;
        if ((poly[mid] - o).cross(p - o) >= 0) lo = mid; else hi = mid;
    }
    long long c = (poly[lo + 1] - poly[lo]).cross(p - poly[lo]);
    if (c < 0) return 0;                           // za bokiem lo -> lo+1
    if (c == 0) return 1;                          // na boku lo -> lo+1
    if (lo == 1 && (poly[1] - o).cross(p - o) == 0) return 1;          // na boku o -> poly[1]
    if (lo + 1 == n - 1 && (poly[n - 1] - o).cross(p - o) == 0) return 1;  // na boku poly[n-1] -> o
    return 2;
}

struct P {
    long long x, y;
    P operator+(const P &o) const { return {x + o.x, y + o.y}; }
    P operator-(const P &o) const { return {x - o.x, y - o.y}; }
    bool operator==(const P &o) const { return x == o.x && y == o.y; }
    bool operator<(const P &o) const { return x != o.x ? x < o.x : y < o.y; }
    long long cross(const P &o) const { return x * o.y - y * o.x; }
    long long dot(const P &o) const { return x * o.x + y * o.y; }
    long long norm2() const { return x * x + y * y; }
};

// Liczba nawinięć (winding number) wielokąta wokół p (p nie na brzegu). != 0 => p wewnątrz.
int windingNumber(const vector<P> &poly, P p) {
    int n = poly.size(), wn = 0;
    for (int i = 0; i < n; i++) {
        P a = poly[i], b = poly[(i + 1) % n];
        if (a.y <= p.y) {
            if (b.y > p.y && (b - a).cross(p - a) > 0) wn++;    // bok w górę, p na lewo
        } else {
            if (b.y <= p.y && (b - a).cross(p - a) < 0) wn--;   // bok w dół, p na prawo
        }
    }
    return wn;
}

