// Sortowanie kątowe wektorów wokół (0, 0): kąt od 0 (dodatnia półoś x) przeciwnie do wskazówek zegara
// do 2π; przy tym samym kierunku bliższy pierwszy. Bez atan2 — dokładnie w long long.
int half(P a) { return (a.y < 0 || (a.y == 0 && a.x < 0)) ? 1 : 0; }   // 0: kąt w [0, π), 1: [π, 2π)
bool angleLess(P a, P b) {
    int ha = half(a), hb = half(b);
    if (ha != hb) return ha < hb;
    long long c = a.cross(b);
    if (c != 0) return c > 0;                    // b na lewo od a => a ma mniejszy kąt
    return a.norm2() < b.norm2();
}

int main() {
    int n;
    cin >> n;
    vector<P> v(n);
    for (auto &p : v) cin >> p.x >> p.y;
    sort(v.begin(), v.end(), angleLess);
    for (auto &p : v) cout << p.x << " " << p.y << "\n";
}

